import 'package:flutter/material.dart';
import 'package:ridex/features/rider_payments/models/rider_receipt_state.dart';

/// Read-only receipt status. A receipt number is shown only after an
/// independently verified canonical read for the exact Trip and Payment.
/// No network URL, download action, or receipt is generated by this widget.
class RiderReceiptPanel extends StatelessWidget {
  const RiderReceiptPanel({super.key, required this.state, this.onRecheck});

  final RiderReceiptState state;
  final VoidCallback? onRecheck;

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).colorScheme;
    final receipt = switch (state) {
      RiderReceiptVerified(:final receipt) => receipt,
      _ => null,
    };
    final message = switch (state) {
      RiderReceiptUnavailable() => 'Receipt verification is unavailable.',
      RiderReceiptLoading() => 'Checking canonical receipt evidence.',
      RiderReceiptUnknown() =>
        'Receipt outcome is unknown. Recheck verified evidence.',
      RiderReceiptNotIssued() =>
        'No receipt was returned by the canonical receipt read.',
      RiderReceiptReadError() => 'Receipt could not be verified.',
      RiderReceiptVerified() => 'Verified receipt is available.',
    };
    final canRecheck = onRecheck != null &&
        (state is RiderReceiptReadError || state is RiderReceiptUnknown);

    return Semantics(
      liveRegion: true,
      label: 'Receipt status. $message',
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(16),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Row(
                children: [
                  Icon(Icons.receipt_long_outlined, color: colors.primary),
                  const SizedBox(width: 12),
                  const Expanded(
                    child: Text(
                      'Receipt',
                      style: TextStyle(fontWeight: FontWeight.bold),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              Text(message, key: const ValueKey('rider-receipt-status')),
              if (state is RiderReceiptLoading) ...[
                const SizedBox(height: 12),
                const LinearProgressIndicator(),
              ],
              if (receipt != null) ...[
                const SizedBox(height: 8),
                Text(
                  'Receipt: ${receipt.receiptNumber}',
                  key: const ValueKey('rider-verified-receipt-number'),
                ),
              ],
              if (canRecheck) ...[
                const SizedBox(height: 12),
                TextButton(
                  key: const ValueKey('rider-receipt-recheck'),
                  onPressed: onRecheck,
                  child: const Text('Recheck receipt'),
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }
}
